import{_ as l,o as t,c as e,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Migrating AI/ML Data Pipelines for Real Time Streaming Applications from HDFS to Ceph - V. Alinouri","description":"","frontmatter":{"title":"Migrating AI/ML Data Pipelines for Real Time Streaming Applications from HDFS to Ceph - V. Alinouri","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","AI/ML","Data Pipeline","HDFS","Real-time Streaming"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Migrating_AI_ML_Data_Pipelines_for_Real_Time_Streaming_Applications_from_HDFS_to_Ceph_-_V._Alinouri.md","filePath":"posts/2025/Migrating_AI_ML_Data_Pipelines_for_Real_Time_Streaming_Applications_from_HDFS_to_Ceph_-_V._Alinouri.md","lastUpdated":1780459816000}'),r={name:"posts/2025/Migrating_AI_ML_Data_Pipelines_for_Real_Time_Streaming_Applications_from_HDFS_to_Ceph_-_V._Alinouri.md"};function o(n,i,s,_,p,g){return t(),e("div",null,[...i[0]||(i[0]=[a('<h3 id="会议纪要-从hdfs迁移到ceph的ai-ml实时流应用项目" tabindex="-1">会议纪要：从HDFS迁移到Ceph的AI/ML实时流应用项目 <a class="header-anchor" href="#会议纪要-从hdfs迁移到ceph的ai-ml实时流应用项目" aria-label="Permalink to &quot;会议纪要：从HDFS迁移到Ceph的AI/ML实时流应用项目&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题： <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题：&quot;">​</a></h4><p>本次会议讨论了将AI/ML实时流应用从HDFS迁移到Ceph存储系统的项目，包括项目背景、问题定义、架构设计、实施过程、性能调优、测试结果和经验教训。</p><h4 id="会议内容" tabindex="-1">会议内容： <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容：&quot;">​</a></h4><ol><li><p><strong>公司背景与项目概述</strong>：</p><ul><li>公司是一家旅游科技公司，专注于机票销售和合作伙伴合作。</li><li>项目目标是解决HDFS在实时流应用中的性能和效率问题，将其迁移到Ceph。</li></ul></li><li><p><strong>问题定义</strong>：</p><ul><li>HDFS存在以下问题： <ul><li><strong>数据存储效率</strong>：仅支持文件存储，无法满足块或对象存储需求。</li><li><strong>小文件管理</strong>：生成大量小文件，管理困难。</li><li><strong>生命周期管理</strong>：缺乏内置工具管理冷热数据。</li><li><strong>弹性与恢复能力</strong>：高峰期性能下降，导致集群崩溃。</li><li><strong>时间效率</strong>：支持批处理，不适合实时应用。</li><li><strong>成本效率</strong>：使用企业级解决方案成本高。</li></ul></li></ul></li><li><p><strong>架构设计</strong>：</p><ul><li>使用Ceph作为底层存储，部署在公司数据中心的私有云上。</li><li>上层应用包括Kubernetes、Spark、Kafka等，使用Ceph的PVC作为本地存储。</li><li>业务逻辑包括价格查询、流数据处理、机器学习模型训练等。</li></ul></li><li><p><strong>实施过程</strong>：</p><ul><li><strong>硬件调优</strong>：禁用CPU的C状态以减少延迟，禁用NUMA以提高性能。</li><li><strong>网络配置</strong>：使用RDMA技术优化集群网络性能。</li><li><strong>内存与性能调优</strong>：调整OSD内存目标、RBD配置、RADOS Gateway实例数等，优化性能。</li><li><strong>数据缓存</strong>：使用Ceph内置的缓存机制，如RADOS Gateway的缓存，提升读写性能。</li></ul></li><li><p><strong>性能测试与调优</strong>：</p><ul><li>使用FIO和Warp进行基准测试，模拟真实场景的负载。</li><li>调整OSD的配置参数，如最大IOPS、内存分配等，确保性能达到预期。</li><li>测试结果显示，Ceph在延迟和IOPS方面显著优于HDFS，尤其是在高负载情况下。</li></ul></li><li><p><strong>经验教训</strong>：</p><ul><li><strong>性能调优</strong>：即使硬件性能高，仍需进行细致的调优，避免使用默认配置。</li><li><strong>动态分片</strong>：合理设置分片数，避免分片过程中的性能瓶颈。</li><li><strong>安全性</strong>：为每个应用和操作员分配独立的权限，确保数据安全。</li></ul></li><li><p><strong>最终结果</strong>：</p><ul><li>使用3台OSD服务器，Ceph在延迟和IOPS方面表现优异，延迟仅为毫秒级，IOPS达到每分钟5000次，显著优于HDFS。</li><li>项目成功展示了Ceph在实时流应用中的优势，管理层已同意增加硬件投入，并计划将网络带宽提升至100Gbps。</li></ul></li><li><p><strong>后续行动计划</strong>：</p><ul><li>继续扩展Ceph集群，增加更多OSD服务器。</li><li>提升网络带宽，确保在高峰期不会成为性能瓶颈。</li><li>进一步优化冷数据存储方案，考虑使用Erasure Coding等技术。</li></ul></li></ol><h4 id="会议总结" tabindex="-1">会议总结： <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结：&quot;">​</a></h4><p>本次会议详细讨论了从HDFS迁移到Ceph的项目实施过程，展示了Ceph在实时流应用中的性能优势，并为未来的扩展和优化提供了明确的方向。</p>',7)])])}const S=l(r,[["render",o]]);export{u as __pageData,S as default};
